#!/usr/bin/env node
// Post-processes the collection generated by `postman spec generate collection`
// so it is usable as-is: auth from environment variables, no placeholder
// credentials, fresh idempotency keys, and unambiguous request names.
// Safe to run repeatedly.

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import YAML from 'yaml';

const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const collectionDir = path.join(
  repoRoot,
  'postman/collections',
  process.argv[2] || 'Porkbun API v3',
);

const CREDENTIAL_HEADERS = new Set(['x-api-key', 'x-secret-api-key']);
const CREDENTIAL_BODY_FIELDS = ['apikey', 'secretapikey'];

const FOLDER_ORDER = [
  'Utility',
  'API Key Management',
  'Pricing',
  'Domain',
  'Porkbun DNS',
  'DNS',
  'SSL',
  'Email',
  'Hosting',
  'Cloudflare',
  'Webhooks',
  'Account',
  'Marketplace',
  'Aftermarket',
  'Closeouts',
  'Sandbox',
  'Mock',
];

const AUTH_SCRIPT = `// Porkbun authenticates with two headers. Set apiKey and secretApiKey in
// the active environment; they are added to every request when present.
const apiKey = pm.variables.get('apiKey');
const secretApiKey = pm.variables.get('secretApiKey');

if (apiKey && secretApiKey) {
  pm.request.headers.upsert({ key: 'X-API-Key', value: apiKey });
  pm.request.headers.upsert({ key: 'X-Secret-API-Key', value: secretApiKey });
}`;

const readYaml = (file) => YAML.parse(fs.readFileSync(file, 'utf8'));
const writeYaml = (file, data) =>
  fs.writeFileSync(file, YAML.stringify(data, { lineWidth: 0, blockQuote: 'literal' }));

function normalizeHeaders(headers) {
  if (!headers) return [];
  if (Array.isArray(headers)) return headers;
  return Object.entries(headers).map(([key, value]) => ({ key, value: String(value) }));
}

function stripBodyCredentials(body) {
  if (!body || body.type !== 'json' || typeof body.content !== 'string') return;
  let parsed;
  try {
    parsed = JSON.parse(body.content);
  } catch {
    return;
  }
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return;
  for (const field of CREDENTIAL_BODY_FIELDS) delete parsed[field];
  body.content = Object.keys(parsed).length ? JSON.stringify(parsed, null, 2) : '{}';
}

function processRequest(request) {
  const headers = normalizeHeaders(request.headers)
    .filter((h) => !CREDENTIAL_HEADERS.has(String(h.key).toLowerCase()))
    .map((h) =>
      String(h.key).toLowerCase() === 'idempotency-key' ? { ...h, value: '{{$guid}}' } : h,
    );
  if (headers.length) request.headers = headers;
  else delete request.headers;

  stripBodyCredentials(request.body);
  delete request.auth;

  for (const pv of request.pathVariables || []) {
    if (pv.key === 'domain' && /^\(Required\)\s*$/.test(pv.description || '')) {
      pv.description = '(Required) Domain name, e.g. example.com';
    }
  }
}

function listDirs(dir) {
  return fs
    .readdirSync(dir, { withFileTypes: true })
    .filter((e) => e.isDirectory() && e.name !== '.resources')
    .map((e) => path.join(dir, e.name));
}

function processFolder(dir) {
  const requestFiles = fs
    .readdirSync(dir)
    .filter((f) => f.endsWith('.request.yaml'))
    .map((f) => path.join(dir, f));

  const entries = requestFiles.map((file) => {
    const stem = path.basename(file, '.request.yaml');
    const data = readYaml(file);
    return { file, stem, data, name: data.name || stem };
  });

  for (const entry of entries) processRequest(entry.data);

  // The spec exposes many reads as both GET and POST under the same summary;
  // label each variant by method so they are distinguishable in Postman.
  const byName = new Map();
  for (const entry of entries) {
    const list = byName.get(entry.name) || [];
    list.push(entry);
    byName.set(entry.name, list);
  }
  for (const [name, group] of byName) {
    if (group.length < 2) continue;
    for (const entry of group) entry.name = `${name} (${entry.data.method})`;
  }

  for (const entry of entries) {
    const newStem = entry.name.replace(/[/\\:*?"<>|]/g, '-');
    const { name, ...rest } = entry.data;
    const data =
      newStem === entry.name ? { $kind: rest.$kind, ...rest } : { $kind: rest.$kind, name: entry.name, ...rest };

    if (newStem !== entry.stem) {
      const oldExamples = path.join(dir, '.resources', `${entry.stem}.resources`);
      const newExamples = path.join(dir, '.resources', `${newStem}.resources`);
      if (fs.existsSync(oldExamples)) fs.renameSync(oldExamples, newExamples);
      if (data.examples) data.examples = `./.resources/${newStem}.resources/examples`;
      fs.rmSync(entry.file);
    }
    writeYaml(path.join(dir, `${newStem}.request.yaml`), data);
  }

  for (const sub of listDirs(dir)) processFolder(sub);
}

function processDefinition() {
  const file = path.join(collectionDir, '.resources/definition.yaml');
  const def = readYaml(file);

  const vars = def.variables && !Array.isArray(def.variables) ? def.variables : {};
  def.variables = {
    baseUrl: vars.baseUrl || 'https://api.porkbun.com/api/json/v3',
    apiKey: '',
    secretApiKey: '',
  };
  delete def.auth;
  def.scripts = [{ type: 'http:beforeRequest', language: 'text/javascript', code: AUTH_SCRIPT }];
  writeYaml(file, def);
}

function orderFolders() {
  for (const dir of listDirs(collectionDir)) {
    const folder = path.basename(dir);
    const index = FOLDER_ORDER.indexOf(folder);
    if (index === -1) continue;
    const file = path.join(dir, '.resources/definition.yaml');
    const def = fs.existsSync(file) ? readYaml(file) : { $kind: 'collection' };
    def.order = (index + 1) * 1000;
    writeYaml(file, def);
  }
}

if (!fs.existsSync(collectionDir)) {
  console.error(`Collection not found: ${collectionDir}`);
  process.exit(1);
}

processDefinition();
for (const dir of listDirs(collectionDir)) processFolder(dir);
orderFolders();
console.log(`Post-processed ${path.relative(repoRoot, collectionDir)}`);
